package io.github.ningpp.compat;

/**
 * Replacement for System.Buffers.StandardFormat (generated by CSharpToJava converter).
 */
public final class StandardFormat {
    private final char symbol;
    private final byte precision;

    /** Default format — 'G' with no precision. */
    public StandardFormat() {
        this('G', (byte) 0xFF);
    }

    /** Mirrors StandardFormat(char symbol). */
    public StandardFormat(char symbol) {
        this(symbol, (byte) 0xFF);
    }

    /** Mirrors StandardFormat(char symbol, byte precision). */
    public StandardFormat(char symbol, byte precision) {        this.symbol = symbol;
        this.precision = precision;
    }

    /** Convenience overload for call sites that pass an int precision (e.g. `(4) & 0xFF`). */
    public StandardFormat(char symbol, int precision) {
        this(symbol, (byte) precision);
    }

    public char getSymbol() {
        return symbol;
    }

    public byte getPrecision() {
        return precision;
    }

    public boolean getIsDefault() {
        return symbol == 'G' && precision == (byte) 0xFF;
    }

    @Override
    public String toString() {
        if (symbol == 'G' && precision == (byte) 0xFF) {
            return "G";
        }
        if (precision == (byte) 0xFF) {
            return String.valueOf(symbol);
        }
        return String.valueOf(symbol) + precision;
    }
}
